import{_ as t,l as o,o as e,c as r,v as i,p as d,x as l,d as s,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"蒙代尔–弗莱明","description":"","frontmatter":{"title":"蒙代尔–弗莱明","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mundell-fleming.md","filePath":"econ/mundell-fleming.md","lastUpdated":1789023840000}'),h={name:"econ/mundell-fleming.md"};function c(P,a,m,B,A,u){const n=o("Mermaid");return e(),r("div",null,[a[1]||(a[1]=i('<h1 id="蒙代尔–弗莱明" tabindex="-1">蒙代尔–弗莱明 <a class="header-anchor" href="#蒙代尔–弗莱明" aria-label="Permalink to &quot;蒙代尔–弗莱明&quot;">​</a></h1><div class="epigraph"><p>资本高度流动时，固定汇率下货币政策让给汇率锚，财政政策对产出更有效；浮动则相反——这是 IS–LM 加上外部平衡，不是新的恒等。</p><footer>—— Mundell, Capital Mobility and Stabilization Policy under Fixed and Flexible Exchange Rates, Canadian Journal of Economics 1963；Fleming 1962</footer></div><p><a href="/econ/j-curve">上一课</a>（J 曲线）。给出长期相对 PPP。短期价格粘住，\\(E\\) 与 \\(i\\) 由资产与商品市场出清。本课把<a href="/econ/is-lm">Hicks 的 IS–LM</a>加上净出口与资本流动：Mundell（1963）与 Fleming（1962）的装置。\\(CA=S-I\\) 仍是恒等；BP 曲线是事前的外部均衡轨迹。不可能三角是下一课把三种制度目标收成三选二。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>封闭 IS–LM 没有 \\(E\\)。开放后，净出口依赖实际汇率与外国收入，资本流动依赖利率差。完全资本流动时，本国 \\(i\\) 必须等于外国 \\(i^*\\)（风险贴水先忽略）——否则资本无限流动。缺口是：在 \\(P\\) 粘性的短局里，财政与货币各能移动 \\(Y\\) 多少，取决于 \\(E\\) 是被钉住还是被市场决定。</p><p>Mundell 的命题用的是流量 IS 与静态预期，不是欧拉 + UIP 的完整 NK 开放。本课用原装置看清制度分叉；Woodford 式的开放 NK 是同一逻辑的前瞻版，不在这里重估系数。</p><p><span class="marginnote">未抛补利率平价 \\(i=i^*+\\mathbb{E}\\Delta e\\) 把静态的 \\(i=i^*\\) 变成带预期贬值的版本。PPP 慢、UIP 快，是短期 \\(q\\) 波动的来源。CIP 在量化栏，有抛补、有远期。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IS：\\(Y=C(Y-T)+I(i)+G+NX(q,Y,Y^*)\\)，\\(q\\) 依 \\(E\\)（\\(P,P^*\\) 粘住）。LM：仍可写 \\(M/P=L(Y,i)\\)，或直接用利率规则。BP：资本流动与 \\(CA\\) 使外汇市场出清。完全流动、静态预期、固定汇率：央行必须内生 \\(M\\) 以维持 \\(E\\)，LM 失去独立；\\(G\\) 移 IS，\\(Y\\) 可升，储备流动。浮动：\\(M\\)（或 \\(i\\)）可独立，\\(G\\) 升推高 \\(i\\)、\\(E\\) 升值，\\(NX\\) 挤出，\\(Y\\) 效果弱；货币扩张贬值并抬 \\(Y\\)。</p>',9)),(e(),d(p,null,{default:l(()=>[E(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIX%5B%22%E5%9B%BA%E5%AE%9A%20E%22%5D%20--%3E%20MON%5B%22%E8%B4%A7%E5%B8%81%E5%86%85%E7%94%9F%EF%BC%8C%E8%B4%A2%E6%94%BF%E7%9B%B8%E5%AF%B9%E6%9C%89%E6%95%88%22%5D%0A%20%20FLT%5B%22%E6%B5%AE%E5%8A%A8%20E%22%5D%20--%3E%20MON2%5B%22%E8%B4%A7%E5%B8%81%E7%9B%B8%E5%AF%B9%E6%9C%89%E6%95%88%EF%BC%8C%E8%B4%A2%E6%94%BF%E8%A2%AB%E6%8C%A4%E5%87%BA%22%5D%0A%20%20IS%5B%22IS%2BNX%22%5D%20--%3E%20Y%5B%22%E4%BA%A7%E5%87%BA%20Y%22%5D%0A%20%20CAP%5B%22%E8%B5%84%E6%9C%AC%E6%B5%81%E5%8A%A8%22%5D%20--%3E%20IEQ%5B%22i%20%E9%9D%A0%E8%BF%91%20i*%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>长期 \\(P\\) 动，PPP 拉回 \\(q\\)，货币中性恢复：固定汇率下本国通胀被锚到外国；浮动下本国选 \\(\\pi\\)， \\(E\\) 去对齐。这与 Friedman 的浮动主张相容：要独立的 \\(\\pi\\) 路径，就不要把 \\(E\\) 钉死。</p><h3 id="仍是会计加均衡" tabindex="-1">仍是会计加均衡 <a class="header-anchor" href="#仍是会计加均衡" aria-label="Permalink to &quot;仍是会计加均衡&quot;">​</a></h3><p>\\(CA\\) 事后等于 \\(S-I\\)。MF 的「外部平衡」是计划的 \\(CA\\) 与资本流动相容。储备变化使固定汇率下金融账户去补。不要把 BP 画成对恒等的否定。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>固定汇率加资本流动：任何想把 \\(i\\) 打下 \\(i^*\\) 的货币扩张，会被资本流出冲掉储备，\\(M\\) 缩回。财政扩张提高 \\(Y\\) 与货币需求，为维持 \\(E\\) 与 \\(i=i^*\\)，央行被动扩 \\(M\\)，于是财政显得「更有效」——其实是货币被迫配合。浮动则汇率承担调整：货币扩张贬值，支出转换强化乘数；财政升值，支出转换削弱乘数。</p><p>下限与非常规在开放下变成汇率与资本流：若 \\(i\\) 卡在零，浮动仍可能靠 \\(E\\) 贬值提供刺激，但竞争性贬值与外国下限是外溢，本课只点明渠道。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>静态 MF 没有微观基础的 NX，没有风险溢价，对大国 \\(i^*\\) 内生。资本管制把完全流动拿掉，制度分叉改变——正是下一课三角。也不要把 MF 写成对量化栏限价簿的外汇订单。长期增长与 \\(A\\) 仍由索洛–内生增长决定，MF 是对 \\(y^*\\) 的短期偏离。</p><p>预期贬值时 \\(i=i^*+\\Delta e^e\\)，钉住若不可信，\\(i\\) 可以暂时离开 \\(i^*\\)，储备仍有限。Dornbusch 超调把理性预期与粘性 \\(P\\) 写成 \\(E\\) 先过调，是动态补丁，主干不重导。CIP 的短端会计在<a href="/quant/irp">利率平价</a>；本课的 \\(i=i^*\\) 是宏观教学版，不是掉期报价。</p><p><span class="marginnote">完美流动极限：浮动时财政完全被升值挤出，货币经贬值有效。钉住时货币被储备冲销，财政有效。不完全流动介于两极端。</span></p><h2 id="边界-1" tabindex="-1">边界 <a class="header-anchor" href="#边界-1" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>后课默认：资本流动 + 汇率制度决定货币与财政的短有效性。下一课收成不可能三角。福利排序不在 MF 里：浮动的 \\(q\\) 波动与钉住的输入通胀要另评。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>粘性价格短局里，把 IS–LM 加上 \\(NX\\) 与资本流动。</li><li>完全流动时固定汇率让渡货币政策；浮动则财政被汇率挤出。</li><li>长期 PPP 与中性恢复；制度选的是名义锚。</li><li>\\(CA=S-I\\) 仍是恒等；BP 是事前外部均衡。</li><li>UIP/CIP 的市场内容不在此重导。</li><li>出处：Mundell 1963；Fleming 1962。</li></ul>',14))])}const C=t(h,[["render",c]]);export{f as __pageData,C as default};
